function topLevelFolders(folders: string[]): string[] {
  const sorted = [...folders].sort();
  const kept: string[] = [];
  for (const f of sorted) {
    const last = kept[kept.length - 1];
    if (last !== undefined && f.startsWith(last + "/")) continue;
    kept.push(f);
  }
  return kept;
}

