function topLevelFolders(folders: string[]): string[] {
  type Node = { kids: Map<string, Node>; path: string | null };
  const root: Node = { kids: new Map(), path: null };
  for (const f of folders) {
    let cur = root;
    for (const part of f.split("/").slice(1)) {
      let next = cur.kids.get(part);
      if (!next) { next = { kids: new Map(), path: null }; cur.kids.set(part, next); }
      cur = next;
    }
    cur.path = f;
  }
  const out: string[] = [];
  const stack: Node[] = [root];
  while (stack.length) {
    const node = stack.pop()!;
    if (node.path !== null) { out.push(node.path); continue; } // do not descend into a listed folder
    for (const child of node.kids.values()) stack.push(child);
  }
  return out;
}

