    def topLevelFolders(self, folders: List[str]) -> List[str]:
        root = {}
        END = "#"  # not a valid segment name, so it never collides
        for f in folders:
            cur = root
            for part in f.split("/")[1:]:
                cur = cur.setdefault(part, {})
            cur[END] = f
        out, stack = [], [root]
        while stack:
            node = stack.pop()
            if END in node:
                out.append(node[END])  # do not descend into a listed folder
                continue
            stack.extend(node.values())
        return out

